  // Mission cards — the day's one instruction on every role's landing screen.
  'mission.clinician.title': 'Close the loop',
  'mission.clinician.body': 'Sign what is waiting, answer the labs that came back, and finish the visits you started.',
  'mission.nurse.title': 'Keep every patient moving',
  'mission.nurse.body': 'Triage who just arrived, give what is due on the MAR, and hand over nothing half-done.',
  'mission.frontDesk.title': 'Keep the desk moving',
  'mission.frontDesk.body': 'Show the next action clearly so reception can register, check in, route, and close visits.',
  'mission.lab.title': 'Answer every order',
  'mission.lab.body': 'Receive what came in, run what is on the bench, and report every result before the clinician has to ask.',
  'mission.pharmacy.title': 'Dispense safely, every time',
  'mission.pharmacy.body': 'Review what was prescribed, check the interactions, and counsel before anything leaves the counter.',
  'mission.radiology.title': 'Report every study',
  'mission.radiology.body': 'Screen before the table, acquire cleanly, and send every report back to the clinician who asked.',
  'mission.nutrition.title': 'Catch it early',
  'mission.nutrition.body': 'Screen every child, start treatment the same day, and follow up until they are discharged well.',
  'mission.dataEntry.title': 'Keep the record complete',
  'mission.dataEntry.body': 'File today\'s census, close the gaps the quality checks found, and report on time.',
  'mission.state.title': 'Keep the picture current',
  'mission.state.body': 'Chase the counties running behind, read the month\'s alerts, and brief the ministry on time.',
  'mission.superintendent.title': 'Run the hospital by its numbers',
  'mission.superintendent.body': 'Watch the wards, unblock the queues, and act on today\'s critical results and stock-outs.',
  'mission.facility.title': 'Keep every facility ready',
  'mission.facility.body': 'Check staffing, supplies, and submissions across the network, and fix what is falling behind.',
  'mission.payments.title': 'Settle every visit',
  'mission.payments.body': 'Collect what is due, reconcile the day, and clear the claims waiting on a payer.',
  'mission.government.title': 'See the whole system',
  'mission.government.body': 'Track reporting across every state, act on surveillance alerts, and steer resources where the data points.',
  'mission.admin.title': 'Keep the platform healthy',
  'mission.admin.body': 'Provision access, resolve conflicts, and keep every tenant syncing.',
